use super::*;

/// The components PHP returns, as key and value, or `None` for `false`.
type Components = Option<&'static [(&'static str, &'static str)]>;

/// What PHP 8.5's `parse_url()` returns for each URL, generated by running
/// it.
const PARSE_URL_CASES: &[(&str, Components)] = &[
    (
        "http://abc.def",
        Some(&[("scheme", "http"), ("host", "abc.def")]),
    ),
    ("abc.def", Some(&[("path", "abc.def")])),
    ("", Some(&[("path", "")])),
    (
        "http://user:pass@host:8080/p/a/t/h?query=1#frag",
        Some(&[
            ("scheme", "http"),
            ("host", "host"),
            ("port", "8080"),
            ("user", "user"),
            ("pass", "pass"),
            ("path", "/p/a/t/h"),
            ("query", "query=1"),
            ("fragment", "frag"),
        ]),
    ),
    ("a.com:80", Some(&[("host", "a.com"), ("port", "80")])),
    (
        "a.com:80/x",
        Some(&[("host", "a.com"), ("port", "80"), ("path", "/x")]),
    ),
    (
        "//example.com/path",
        Some(&[("host", "example.com"), ("path", "/path")]),
    ),
    (
        "mailto:me@x.org",
        Some(&[("scheme", "mailto"), ("path", "me@x.org")]),
    ),
    (
        "file:///c:/dir/f.txt",
        Some(&[("scheme", "file"), ("path", "c:/dir/f.txt")]),
    ),
    (
        "file:///etc/passwd",
        Some(&[("scheme", "file"), ("path", "/etc/passwd")]),
    ),
    (
        "http://[::1]:80/",
        Some(&[
            ("scheme", "http"),
            ("host", "[::1]"),
            ("port", "80"),
            ("path", "/"),
        ]),
    ),
    ("http:///x", None),
    ("http://host:99999", None),
    (
        "http://host:",
        Some(&[("scheme", "http"), ("host", "host")]),
    ),
    ("http://:80", None),
    (
        "/path?x#",
        Some(&[("path", "/path"), ("query", "x"), ("fragment", "")]),
    ),
    ("x?", Some(&[("path", "x"), ("query", "")])),
    (":80", None),
    ("foo:bar", Some(&[("scheme", "foo"), ("path", "bar")])),
    (
        "http://h/p?q#f#g",
        Some(&[
            ("scheme", "http"),
            ("host", "h"),
            ("path", "/p"),
            ("query", "q"),
            ("fragment", "f#g"),
        ]),
    ),
    ("ht!tp://x", Some(&[("path", "ht!tp://x")])),
    ("a:65535", Some(&[("host", "a"), ("port", "65535")])),
    ("a:123456", Some(&[("scheme", "a"), ("path", "123456")])),
    (
        "http://u@h",
        Some(&[("scheme", "http"), ("host", "h"), ("user", "u")]),
    ),
    ("?a=b", Some(&[("query", "a=b")])),
    ("#frag", Some(&[("fragment", "frag")])),
    ("http:", Some(&[("scheme", "http")])),
    ("http:/x", Some(&[("scheme", "http"), ("path", "/x")])),
    (
        "https://ex.com:0443",
        Some(&[("scheme", "https"), ("host", "ex.com"), ("port", "443")]),
    ),
    (
        "http://h:12ab/x",
        Some(&[
            ("scheme", "http"),
            ("host", "h"),
            ("port", "12"),
            ("path", "/x"),
        ]),
    ),
    ("//h:", Some(&[("host", "h")])),
    ("a/b:c", Some(&[("path", "a/b:c")])),
    (
        "x:1?y=2:3",
        Some(&[("scheme", "x"), ("path", "1"), ("query", "y=2:3")]),
    ),
];

#[test]
fn parses_like_php() {
    for (url, expected) in PARSE_URL_CASES {
        let parsed = parse(url.as_bytes()).expect("no control characters");
        let actual: Option<Vec<(&str, String)>> = parsed.map(|parsed| {
            (0..KEYS.len())
                .filter_map(|index| {
                    let value = if index == 2 {
                        parsed.port?.to_string()
                    } else {
                        String::from_utf8_lossy(parsed.parts[index]?).into_owned()
                    };
                    Some((KEYS[index], value))
                })
                .collect()
        });
        let expected: Option<Vec<(&str, String)>> = expected.map(|parts| {
            parts
                .iter()
                .map(|(key, value)| (*key, value.to_string()))
                .collect()
        });
        assert_eq!(actual, expected, "parse_url({url:?})");
    }
}

#[test]
fn leaves_control_characters_undecided() {
    assert!(parse(b"http://a\tb").is_none());
}
